using Registry=suitecut::SnapshotReferences;
struct Harness {
 using Ack=std::function<void(bool,const std::string&)>;
 struct Release{std::string frame,session;Ack done;};
 std::vector<Release> releases;std::vector<std::string> errors;std::set<std::string> stale;std::map<std::string,Registry::Document> changed;
 Registry refs{"actualBatchSource",[this](int,uint64_t,const Registry::Document&doc){const auto current=changed.find(doc.frame);return !stale.contains(doc.frame)&&(current==changed.end()||current->second==doc);},[this](const Registry::Group&group,Ack done){releases.push_back({group.document.frame,group.document.session,std::move(done)});},[this](const std::string&error){errors.push_back(error);}};
 static Registry::Document Doc(int index){return{"frame"+std::to_string(index),index?"actualOOPIF":"","loader"+std::to_string(index),"mainUnique"+std::to_string(index),"utilityUnique"+std::to_string(index),index*2+11,index*2+12,7};}
 uint64_t Stage(int frame,int count=1,int owner=1,uint64_t generation=1,double deadline=1000){std::vector<Registry::Node> nodes;for(int i=0;i<count;++i)nodes.push_back({i+100,1});auto ticket=refs.Begin(owner,generation,Doc(frame),std::move(nodes),deadline,0);assert(ticket);return ticket;}
 void Install(uint64_t ticket){assert(refs.Dispatched(ticket));assert(refs.Installed(ticket,true,"actual-native-retained-array",1));}
 uint64_t Published(int frame,int count=1){const auto ticket=Stage(frame,count);Install(ticket);assert(refs.Commit(ticket,2));return ticket;}
 void AckAll(){for(size_t i=0;i<releases.size();++i){const auto done=releases[i].done;done(true,"");}}
 void Empty(){assert(!refs.Active()&&!refs.Resident()&&!refs.Groups()&&!refs.Bytes()&&!refs.Physical()&&!refs.InstallPhysical()&&!refs.Borrows());}
 void Destroy(){refs.ChannelDestroyed("");refs.ChannelDestroyed("actualOOPIF");Empty();}
};
