 {Harness h;const auto old_main=h.Published(0),old_child=h.Published(1);const auto main_ref=h.refs.Reference(old_main,0),child_ref=h.refs.Reference(old_child,0);const auto main=h.Stage(0),child=h.Stage(1);h.Install(main);h.Install(child);assert(h.refs.CommitBatch({main,child},3));assert(h.refs.Lookup(main_ref,Harness::Doc(0))&&h.refs.Lookup(child_ref,Harness::Doc(1)));assert(!h.refs.Reference(main,0).empty()&&!h.refs.Reference(child,0).empty());assert(h.refs.Active()==2&&h.refs.Resident()==4&&h.refs.Physical()==2&&h.releases.size()==2);h.AckAll();assert(h.refs.Resident()==2);h.Destroy();++groups;}
 for(int invalid=0;invalid<6;++invalid){Harness h;const auto old_main=h.Published(0),old_child=h.Published(1);const auto main_ref=h.refs.Reference(old_main,0),child_ref=h.refs.Reference(old_child,0);const auto main=h.Stage(0),child=h.Stage(1);h.Install(main);if(invalid!=0)h.Install(child);if(invalid==1)h.stale.insert("frame1");const double now=invalid==2?1000:3;std::vector<uint64_t> batch{main,invalid==3?99999u:child};if(invalid==4)batch[1]=old_child;if(invalid==5)batch[1]=main;assert(!h.refs.CommitBatch(batch,now));h.stale.clear();assert(h.refs.Lookup(main_ref,Harness::Doc(0))&&h.refs.Lookup(child_ref,Harness::Doc(1))&&h.refs.Active()==2);assert(h.refs.Reference(main,0).empty()&&h.refs.Reference(child,0).empty());h.refs.Cancel(1,1,now);h.AckAll();h.Destroy();}++groups;
 {Harness h;const auto old=h.Published(0);const auto token=h.refs.Reference(old,0);const auto one=h.Stage(0),two=h.Stage(0);h.Install(one);h.Install(two);assert(!h.refs.CommitBatch({one,two},3));assert(h.refs.Lookup(token,Harness::Doc(0))&&h.refs.Active()==1&&h.refs.Physical()==2);h.AckAll();h.Destroy();++groups;}
 {Harness h;const auto old_main=h.Published(0),old_child=h.Published(1);assert(!h.refs.Reference(old_child,0).empty());auto borrow=h.refs.Lookup(h.refs.Reference(old_main,0),Harness::Doc(0));const auto main=h.Stage(0),child=h.Stage(1);h.Install(main);h.Install(child);assert(h.refs.CommitBatch({main,child},3));assert(h.refs.Borrows()==1&&h.refs.Active()==2&&h.refs.Resident()==4&&h.refs.Physical()==1);assert(h.releases.front().frame=="frame1"&&h.releases.front().session=="actualOOPIF");h.AckAll();assert(h.refs.Resident()==3);borrow={};assert(h.refs.Physical()==1&&h.releases.back().frame=="frame0"&&h.releases.back().session.empty());h.AckAll();assert(h.refs.Resident()==2);h.Destroy();++groups;}
 for(bool child_first:{false,true}){Harness h;h.Published(0,4096);const auto main=h.Stage(0,0),child=h.Stage(1,4096);h.Install(main);h.Install(child);assert(h.refs.Resident()==8192);assert(h.refs.CommitBatch(child_first?std::vector<uint64_t>{child,main}:std::vector<uint64_t>{main,child},3));assert(h.refs.Active()==4096&&h.refs.Resident()==8192);h.AckAll();assert(h.refs.Resident()==4096);h.Destroy();}++groups;
 {Harness h;const auto old=h.Published(0,4096);const auto token=h.refs.Reference(old,0);const auto main=h.Stage(0,4095),child=h.Stage(1,1);h.Install(main);h.Install(child);assert(h.refs.CommitBatch({main,child},3));assert(h.refs.Lookup(token,Harness::Doc(0))&&h.refs.Active()==4096);h.AckAll();h.Destroy();++groups;}
 {Harness h;const auto old=h.Published(0);const auto token=h.refs.Reference(old,0);const auto main=h.Stage(0,4096),child=h.Stage(1,1);h.Install(main);h.Install(child);assert(!h.refs.CommitBatch({main,child},3));assert(h.refs.Lookup(token,Harness::Doc(0))&&h.refs.Active()==1);h.AckAll();h.Destroy();++groups;}
 for(int mismatch=0;mismatch<3;++mismatch){Harness h;const auto old=h.Published(0);const auto token=h.refs.Reference(old,0);const auto main=h.Stage(0),child=h.Stage(1,1,mismatch==0?2:1,mismatch==1?2:1,mismatch==2?999:1000);h.Install(main);h.Install(child);assert(!h.refs.CommitBatch({main,child},3));assert(h.refs.Lookup(token,Harness::Doc(0))&&h.refs.Active()==1);h.AckAll();h.Destroy();}++groups;
 {Harness h;const auto main=h.Stage(0),child=h.Stage(1);h.Install(main);assert(h.refs.Dispatched(child));assert(!h.refs.CommitBatch({main,child},3));assert(h.refs.InstallPhysical()==1&&h.refs.Resident()==2&&h.refs.Physical()==1);h.AckAll();assert(h.refs.Resident()==1&&h.refs.InstallPhysical()==1);assert(!h.refs.Installed(child,true,"actual-late-child-array",4));assert(h.refs.Physical()==1);h.AckAll();h.Empty();++groups;}
 {Harness h;const auto old=h.Published(0);const auto token=h.refs.Reference(old,0);const auto main=h.Stage(0),child=h.Stage(1);h.Install(main);h.Install(child);h.refs.ChannelDestroyed("actualOOPIF");assert(!h.refs.CommitBatch({main,child},3));assert(h.refs.Lookup(token,Harness::Doc(0))&&h.refs.Active()==1);h.AckAll();h.Destroy();++groups;}
 {Harness h;const auto old=h.Published(0);const auto token=h.refs.Reference(old,0);const auto main=h.Stage(0),child=h.Stage(1);h.Install(main);h.Install(child);const auto newer=h.Published(1);assert(!h.refs.CommitBatch({main,child},4));assert(h.refs.Lookup(token,Harness::Doc(0))&&h.refs.Active()==2&&!h.refs.Reference(newer,0).empty());h.AckAll();h.Destroy();++groups;}
 {Harness h;std::vector<uint64_t> batch;for(int i=0;i<33;++i){const auto t=h.Stage(i);h.Install(t);batch.push_back(t);}assert(!h.refs.CommitBatch(batch,3)&&!h.refs.Active());h.refs.Cancel(1,1,3);h.AckAll();h.Destroy();++groups;}
 for(int field=0;field<8;++field){Harness h;const auto old_main=h.Published(0),old_child=h.Published(1);const auto main_ref=h.refs.Reference(old_main,0),child_ref=h.refs.Reference(old_child,0);const auto main=h.Stage(0),child=h.Stage(1);h.Install(main);h.Install(child);auto actual=Harness::Doc(1);switch(field){case 0:actual.loader+="new";break;case 1:actual.session+="new";break;case 2:actual.main_unique+="new";break;case 3:actual.utility_unique+="new";break;case 4:++actual.context_generation;break;case 5:++actual.main;break;case 6:++actual.utility;break;case 7:actual.frame+="new";break;}h.changed["frame1"]=actual;assert(!h.refs.CommitBatch({main,child},3));h.changed.clear();assert(h.refs.Lookup(main_ref,Harness::Doc(0))&&h.refs.Lookup(child_ref,Harness::Doc(1))&&h.refs.Active()==2);h.AckAll();h.Destroy();}++groups;
 assert(Registry::GlobalResident()==0&&Registry::GlobalInstallPhysical()==0&&Registry::GlobalReleasePhysical()==0);
